#!/usr/bin/env bash
# shellcheck disable=SC1087,SC2329 # false positive and unused helpers in the wizard library
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Release secrets: everything the Release workflow's secrets check asks for, stored
# in the release environment of maddec01/mux-factory, which only main can use.
# Run: bash scripts/release-secrets.sh [--dry-run]
# --dry-run prints each gh command that would change GitHub instead of running it.
# Re-running is safe: it skips an environment or branch policy that already exists
# and replaces the secrets with the values you give it.

REPO=maddec01/mux-factory
ENV_PATH=repos/$REPO/environments/release
DRY_RUN=""
# Nothing is saved to disk, so there are no stored answers to offer on a re-run.
ENV_FILE=/dev/null

die() {
  printf 'release-secrets: %s\n' "$*" >&2
  exit 1
}

# ask_file KEY "Prompt" reads the path of an existing file into $KEY, asking again
# until the file exists. Takes ~/ and a path dragged in from Finder.
ask_file() {
  local key="$1" path
  while :; do
    ask "$key" "$2"
    path=${!key}
    path=${path%"${path##*[![:space:]]}"}
    path=$(printf '%s' "$path" | sed 's/\\\(.\)/\1/g')
    [[ $path == \~/* ]] && path=$HOME/${path#\~/}
    if [[ -f $path ]]; then
      printf -v "$key" '%s' "$path"
      return
    fi
    warn "no file at $path"
  done
}

# ask_until READER KEY "Prompt:" [DEFAULT] [PATTERN "Hint"] reads $KEY with ask or
# ask_secret, asking again until the answer matches PATTERN, which by default takes
# anything but an empty answer. With a DEFAULT, Enter takes it.
ask_until() {
  local reader="$1" key="$2" prompt="$3" default="${4:-}" pattern="${5:-.}"
  local hint="${6:-}"
  [[ -n $hint ]] || hint="This can't be empty."
  [[ -n $default ]] && prompt="${prompt%:} (Enter for $default):"
  while :; do
    "$reader" "$key" "$prompt" || die "stopped: no answer to '$prompt'"
    [[ -z ${!key} && -n $default ]] && printf -v "$key" '%s' "$default"
    [[ ${!key} =~ $pattern ]] && return
    warn "$hint"
  done
}

# gh_write ARGS... runs a gh command that changes GitHub, or prints it in a dry run.
gh_write() {
  if [[ -n $DRY_RUN ]]; then
    printf '  %swould run%s gh %s\n' "$YELLOW" "$RESET" "$*"
    return
  fi
  gh "$@" >/dev/null
}

# done_line "msg" reports a change gh_write made; a dry run made none.
done_line() {
  [[ -n $DRY_RUN ]] || printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"
}

# env_secret NAME stores stdin as the release environment's secret NAME. The value
# reaches gh on stdin, so it never shows in the output or in the process list.
env_secret() {
  local name="$1"
  if [[ -n $DRY_RUN ]]; then
    cat >/dev/null
    printf '  %swould run%s gh secret set %s --env release --repo %s (value on stdin)\n' \
      "$YELLOW" "$RESET" "$name" "$REPO"
    return
  fi
  if gh secret set "$name" --env release --repo "$REPO" >/dev/null; then
    WRITTEN_SECRET+=("$name")
    printf '  %s✓ set%s secret %s\n' "$GREEN" "$RESET" "$name"
  else
    SKIPPED+=("secret $name: gh secret set $name --env release --repo $REPO")
    warn "couldn't set secret $name"
  fi
}

# Prints true when the release environment exists and allows only chosen branches.
env_limited() {
  local out
  out=$(gh api "$ENV_PATH" --jq '.deployment_branch_policy.custom_branch_policies // false' 2>/dev/null) &&
    printf '%s' "$out"
}

# Prints the release environment's branch policy names, one per line.
# gh prints a 404's body on stdout, so the output counts only when gh succeeds.
branch_policies() {
  local out
  out=$(gh api "$ENV_PATH/deployment-branch-policies" --jq '.branch_policies[].name' 2>/dev/null) &&
    printf '%s' "$out"
}

# warn_others warns about the branch policies other than main in $others. The
# GitHub stage and the closing screen both show it, since the closing screen clears.
warn_others() {
  [[ -n $others ]] || return 0
  warn "the release environment also allows: $(tr '\n' ' ' <<<"$others")"
  note "Remove those in https://github.com/$REPO/settings/environments so only main can release."
}

run_wizard() {

case "${1:-}" in
  "") ;;
  --dry-run) DRY_RUN=1 ;;
  *) die "usage: bash scripts/release-secrets.sh [--dry-run]" ;;
esac

if ! command -v gh >/dev/null 2>&1 || ! gh auth status >/dev/null 2>&1; then
  [[ -n $DRY_RUN ]] || die "needs gh, logged in as an admin of $REPO (gh auth login)"
  warn "gh isn't logged in, so the dry run treats the release environment as missing"
else
  gh_err=$(mktemp)
  if ! admin=$(gh api "repos/$REPO" --jq .permissions.admin 2>"$gh_err"); then
    err=$(<"$gh_err"); rm -f "$gh_err"
    die "couldn't read $REPO's permissions: ${err:-gh api repos/$REPO failed}"
  fi
  rm -f "$gh_err"
  if [[ $admin != true ]]; then
    [[ -n $DRY_RUN ]] || die "the gh account isn't an admin of $REPO, and only an admin can create the release environment and its secrets. Log in as an admin with gh auth login, then run this again."
    warn "the gh account isn't an admin of $REPO, so a real run would stop here. The dry run goes on."
  fi
fi

TOTAL_STAGES=5

banner "Release secrets for $REPO${DRY_RUN:+ (dry run)}"

stage "Apple: Developer ID Application certificate"
say "Only the Account Holder can create this certificate. You need a signing request first."
step "Open Keychain Access. In its menu choose Certificate Assistant > Request a Certificate From a Certificate Authority."
step "Enter your email, leave CA Email empty, choose Saved to disk, and save the .certSigningRequest file."
open_url "https://developer.apple.com/account/resources/certificates/add"
step "Choose Developer ID Application, then Continue. Keep the G2 Sub-CA profile type."
step "Upload the signing request, then Download. Double-click the .cer to add it to your login keychain."
step "In Keychain Access > My Certificates, find 'Developer ID Application: <your name> (<team ID>)'."
step "Right-click it, Export, choose Personal Information Exchange (.p12), and set a password."
note "The .p12 holds the certificate and its private key. Keep it out of this repo."
ask_file P12_PATH "Path to the exported .p12:"
ask_until ask_secret CSC_KEY_PASSWORD "The .p12 password (hidden):"

stage "Apple: App Store Connect API key for notarization"
open_url "https://appstoreconnect.apple.com/access/integrations/api"
step "Under Team Keys, click Generate API Key (or +). The first time, request access first."
step "Name it 'mux-factory notarization', give it the Developer role, and Generate."
step "Download the key. Apple lets you download it only once: AuthKey_<key ID>.p8."
step "The Issuer ID is shown above the keys table; the Key ID is in the key's row."
ask_file P8_PATH "Path to the downloaded .p8:"
key_id_default=""
[[ ${P8_PATH##*/} =~ ^AuthKey_([A-Za-z0-9]+)\.p8$ ]] && key_id_default=${BASH_REMATCH[1]}
ask_until ask APPLE_API_KEY_ID "Key ID:" "$key_id_default"
ask_until ask_secret APPLE_API_ISSUER "Issuer ID (hidden):"

stage "Apple: team ID"
open_url "https://developer.apple.com/account#MembershipDetailsCard"
step "Under Membership details, copy the Team ID. It is also in brackets in the certificate's name."
ask_until ask APPLE_TEAM_ID "Team ID:" "" '^[A-Z0-9]{10}$' "A Team ID is 10 uppercase letters and digits."

stage "GitHub: release environment, main only"
if [[ $(env_limited || true) == true ]]; then
  say "The release environment exists and is already limited to chosen branches."
else
  gh_write api --method PUT "$ENV_PATH" \
    -F 'deployment_branch_policy[protected_branches]=false' \
    -F 'deployment_branch_policy[custom_branch_policies]=true'
  done_line "release environment, limited to chosen branches"
fi
policies=$(branch_policies || true)
if grep -qx main <<<"$policies"; then
  say "The branch policy already allows main."
else
  gh_write api --method POST "$ENV_PATH/deployment-branch-policies" -f name=main -f type=branch
  done_line "branch policy: main"
fi
others=$(grep -vx main <<<"$policies" || true)
warn_others

stage "GitHub: store the secrets"
say "This sets 5 secrets and 1 variable in the release environment, replacing any already there."
stored=""
if confirm "Store them now?"; then
  stored=1
  base64 <"$P12_PATH" | tr -d '\n' | env_secret CSC_LINK
  printf '%s' "$CSC_KEY_PASSWORD" | env_secret CSC_KEY_PASSWORD
  env_secret APPLE_API_KEY <"$P8_PATH"
  printf '%s' "$APPLE_API_KEY_ID" | env_secret APPLE_API_KEY_ID
  printf '%s' "$APPLE_API_ISSUER" | env_secret APPLE_API_ISSUER
  if gh_write variable set APPLE_TEAM_ID --env release --repo "$REPO" --body "$APPLE_TEAM_ID"; then
    done_line "variable APPLE_TEAM_ID"
  else
    SKIPPED+=("variable APPLE_TEAM_ID: gh variable set APPLE_TEAM_ID --env release --repo $REPO")
  fi
fi

if [[ -n $stored ]]; then
  finish
else
  _clear
  printf '\n'
  warn "The secrets and APPLE_TEAM_ID weren't stored. Run bash scripts/release-secrets.sh again to store them."
fi
warn_others
if [[ -n $DRY_RUN ]]; then
  note "Dry run: nothing changed on GitHub."
elif [[ -n $stored ]]; then
  note "The next Release run picks these up. Delete the .certSigningRequest; keep the .p12 and .p8 somewhere safe."
fi
}

run_wizard "$@"; exit
